import Link from "next/link";

export interface Talent {
  slug: string;
  name: string;
  roleType: "Actor" | "Voice" | "Commercial";
  playingAge?: string;
  headshotUrl: string;
}

export function TalentCard({ talent }: { talent: Talent }) {
  return (
    <Link
      href={`/talent/${talent.slug}`}
      className="group rounded-2xl bg-white shadow-card border border-neutral-100 overflow-hidden hover:-translate-y-1 hover:shadow-lg transition"
    >
      <div className="aspect-[3/4] w-full overflow-hidden">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={talent.headshotUrl}
          alt={talent.name}
          className="object-cover h-full w-full group-hover:scale-105 transition-transform"
        />
      </div>

      <div className="p-3">
        <p className="text-sm font-semibold text-neutral-900">{talent.name}</p>

        <p className="text-xs text-neutral-500 mt-1">
          {talent.roleType}
          {talent.playingAge ? ` • Playing age ${talent.playingAge}` : ""}
        </p>

        <p className="text-xs text-brand-primary mt-2 font-medium">
          View profile →
        </p>
      </div>
    </Link>
  );
}
